<script setup>
import { inject, ref } from "vue";
import { call, __ } from "../api";
const props = defineProps({ center: String, direction: { type: String, default: "supply" } });
const emit = defineEmits(["created"]);
const { ctx, notification } = inject("portal");
const dialog = ref(null), source = ref(null), form = ref({}), items = ref([]), busy = ref(""), error = ref(""), operationKey = ref("");
function blank() { return { item_code: "", item_name: "", qty: 1, available_qty: 0 }; }
async function open() { busy.value = "load"; error.value = ""; operationKey.value = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`; dialog.value?.showModal(); try { source.value = await call("an_truck_portal.api.maintenance_centers.get_transfer_form", { center: props.center, company: ctx.company }); form.value = { posting_date: source.value.posting_date, other_warehouse: "", notes: "", items: [blank()] }; } catch (e) { error.value = e.message; } finally { busy.value = ""; } }
function close() { if (!busy.value) dialog.value?.close(); }
async function warehouseChanged() { const warehouse = props.direction === "supply" ? form.value.other_warehouse : source.value.center_warehouse; if (!warehouse) return; try { items.value = await call("an_truck_portal.api.spare_parts_sales.get_item_availability", { company: ctx.company, warehouse }); form.value.items.forEach(selectItem); } catch (e) { error.value = e.message; } }
function selectItem(row) { const item = items.value.find((value) => value.name === row.item_code); if (item) Object.assign(row, { item_name: item.item_name, available_qty: item.available_qty, uom: item.stock_uom }); }
async function save(submitNow) { busy.value = submitNow ? "submit" : "draft"; try { const result = await call("an_truck_portal.api.maintenance_centers.create_transfer", { center: props.center, company: ctx.company, direction: props.direction, data: form.value, submit_now: submitNow ? 1 : 0, idempotency_key: operationKey.value }, true); dialog.value?.close(); notification.value = __("Stock transfer created successfully."); emit("created", result); } catch (e) { error.value = e.message; } finally { busy.value = ""; } }
defineExpose({ open });
</script>
<template><dialog ref="dialog" class="operation-dialog wide-dialog" :aria-label="__(direction === 'supply' ? 'Transfer Company Stock to Center' : 'Return Company Stock')" @cancel.prevent="close"><form @submit.prevent="save(true)"><div class="dialog-head"><div><p class="eyebrow">{{ __("Stock Transfer") }}</p><h2>{{ __(direction === 'supply' ? 'Transfer Company Stock to Center' : 'Return Company Stock') }}</h2></div><button type="button" class="icon" :aria-label="__('Close')" @click="close">×</button></div><div class="dialog-body"><p class="notice compact">{{ __("This is a company-owned stock movement, not a sale or monthly settlement.") }}</p><div class="form-grid"><label><span>{{ __("Posting Date") }}</span><input v-model="form.posting_date" type="date" required /></label><label><span>{{ __(direction === 'supply' ? 'Source Warehouse' : 'Return Warehouse') }}</span><select v-model="form.other_warehouse" required @change="warehouseChanged"><option value="">{{ __("Select") }}</option><option v-for="row in source?.warehouses || []" :key="row.value" :value="row.value">{{ row.label }}</option></select></label><label class="wide"><span>{{ __("Notes") }}</span><textarea v-model="form.notes"></textarea></label></div><div class="dialog-section-head"><h3>{{ __("Items") }}</h3><button type="button" class="button secondary small" @click="form.items.push(blank())">{{ __("+ Add Item") }}</button></div><div class="editable-grid"><div v-for="(row,index) in form.items || []" :key="index" class="edit-row"><label><span>{{ __("Part Number") }}</span><input v-model="row.item_code" list="center-transfer-items" required @change="selectItem(row)" /></label><label><span>{{ __("Item Name") }}</span><input :value="row.item_name" disabled /></label><label><span>{{ __("Available Quantity") }}</span><input :value="`${row.available_qty || 0} ${row.uom || ''}`" disabled /></label><label><span>{{ __("Quantity") }}</span><input v-model.number="row.qty" type="number" min="0" step="any" required /></label><button type="button" class="remove-row" :aria-label="__('Delete')" @click="form.items.splice(index,1)">×</button></div></div><datalist id="center-transfer-items"><option v-for="item in items" :key="item.name" :value="item.name">{{ item.item_name }}</option></datalist><p v-if="error" class="form-error">{{ __(error) }}</p></div><div class="dialog-actions"><button type="button" class="button secondary" :disabled="!!busy" @click="close">{{ __("Cancel") }}</button><button type="button" class="button secondary" :disabled="!!busy" @click="save(false)">{{ __(busy === 'draft' ? 'Saving…' : 'Save Draft') }}</button><button class="button" :disabled="!!busy">{{ __(busy === 'submit' ? 'Processing...' : 'Create and Submit') }}</button></div></form></dialog></template>
